func (r JournalRetention) DeleteExpiredTransfers(ctx context.Context) (int, int, error) {
	now := r.Now()
	cutoff := domain.JournalRetentionCutoff(now)
	deleted, err := r.Journal.DeleteExpired(ctx, cutoff)
	if err != nil {
		return 0, 0, err
	}
	return deleted, int(now.Sub(cutoff).Hours() / 24), nil
}

func (s *Service) Status(ctx context.Context) (exporttransfer.Status, error) {
	state, err := s.targets.State(ctx)
	if err != nil {
		return exporttransfer.Status{}, fmt.Errorf("%w: %w", ErrUnavailable, err)
	}
	return exporttransfer.Status{Enabled: state.Enabled, Ready: state.Ready(), Host: state.Host, Port: state.Port, RemoteDirectory: state.RemoteDirectory, MissingSettings: state.MissingSettings}, nil
}
